import { RendererCanvas } from '../../../../lib';
import { Solution } from '..';


export class RendererCanvasMapbox extends RendererCanvas {
	public app: Solution;
	public time: number = 0.0;
	public scaleGlobal: number = 12;
	public pts: number[][] = [];
	constructor(div: any, app: Solution) {
		super(div);
		this.app = app;
		this.canvas.id = 'mapboxCustom'
		this.canvas.style.position = 'absolute';
		this.canvas.style.width = '100%';
		this.canvas.style.height = '100%';
		this.canvas.style.pointerEvents = 'none';

		this.canvas.style.mixBlendMode = 'screen';
		this.ctx.globalCompositeOperation = 'screen';

		this.scaleGlobal = this.app.mapboxWrapper.map.getZoom()
		this.start();
	}
	public mouseDown = (x: number, y: number): void => {

	}
	public mouseUp = (x: number, y: number): void => {

	}
	public mouseDrag = (x: number, y: number): void => {

	}

	private getPerspectiveScale(lng: number, lat: number): number {
		const map = this.app.mapboxWrapper.map;
		const pitch = map.getPitch();

		if (pitch === 0) return 1.0;

		const screenPos = this.app.mapboxWrapper.toScreen(lng, lat);
		const canvasHeight = this.canvas.height;
		const normalizedY = screenPos[1] / canvasHeight;
		const pitchFactor = pitch / 60.0; // 0~1 normalized pitch

		const perspectiveScale = 0.3 + 0.7 * Math.pow(normalizedY, 1.5);
		return 1.0 - pitchFactor * (1.0 - perspectiveScale);
	}


	private getScale(lng: number, lat: number): number {
		const map = this.app.mapboxWrapper.map;
		const zoom = map.getZoom();

		const referenceZoom = this.scaleGlobal;
		const zoomScale = Math.pow(2, zoom - referenceZoom);
		const perspectiveScale = this.getPerspectiveScale(lng, lat);

		return zoomScale * perspectiveScale;
	}

	private drawPerspectiveCircle(ctx: CanvasRenderingContext2D, lng: number, lat: number, baseRadius: number, segments: number = 32): void {
		const map = this.app.mapboxWrapper.map;
		const zoom = map.getZoom();

		const scale = this.getScale(lng, lat);
		const radius = baseRadius * scale;

		const center = this.app.mapboxWrapper.toScreen(lng, lat);

		const metersPerPixel = 156543.03392 * Math.cos(lat * Math.PI / 180) / Math.pow(2, zoom);
		const radiusInMeters = radius * metersPerPixel;

		const points: number[][] = [];
		for (let i = 0; i <= segments; i++) {
			const angle = (i / segments) * Math.PI * 2;

			const offsetX = Math.cos(angle) * radiusInMeters;
			const offsetY = Math.sin(angle) * radiusInMeters;

			const lngOffset = offsetX / (111320 * Math.cos(lat * Math.PI / 180));
			const latOffset = offsetY / 110540;

			const pointLng = lng + lngOffset;
			const pointLat = lat + latOffset;

			if (pointLng && pointLat) {
				const screenPos = this.app.mapboxWrapper.toScreen(pointLng, pointLat);
				points.push(screenPos);
			} else {
				return;
			}

		}


		if (points.length > 0) {

			if (points[0][0] && points[0][1]) {
				ctx.beginPath();
				ctx.moveTo(points[0][0], points[0][1]);
				for (let i = 1; i < points.length; i++) {
					ctx.lineTo(points[i][0], points[i][1]);
				}
				ctx.closePath();
			}

		}
	}

	public render(ctx: CanvasRenderingContext2D): void {
		this.time += 0.1;

		if (this.pts.length > 1) {
			const avgScale = this.getScale(this.pts[0][0], this.pts[0][1]);
			const baseLineWidth = 1;

			ctx.beginPath();
			const p = this.app.mapboxWrapper.toScreen(this.pts[0][0], this.pts[0][1]);
			ctx.moveTo(p[0], p[1])

			for (let i = 1; i < this.pts.length; ++i) {
				const pt = this.pts[i];
				const p = this.app.mapboxWrapper.toScreen(pt[0], pt[1]);
				ctx.lineTo(p[0], p[1])
			}

			ctx.lineWidth = baseLineWidth * avgScale;
			ctx.strokeStyle = 'rgba(0, 255, 255, 0.5)';
			ctx.stroke();
		}


		for (let i = 0; i < this.pts.length; ++i) {
			const pt = this.pts[i];
			let baseRadius = Math.sin(this.time) * 3 + 15;
			baseRadius = baseRadius > 20 ? 20 : baseRadius;

			this.drawPerspectiveCircle(ctx, pt[0], pt[1], baseRadius, 32);
			ctx.fillStyle = 'rgba(0, 255, 0, 0.5)';
			ctx.fill();
		}
	}
}
