import { MapboxGLWrapper } from './MapboxGLWrapper';

import { RendererCanvasMapbox } from './Renderer/RendererCanvasMapbox';
import { RendererThreeMapbox } from './Renderer/RendererThreeMapbox';
import { UI } from './UI';


export class Solution {
	public divHost: HTMLDivElement;
	public mapboxWrapper: MapboxGLWrapper;
	public rendererCanvas: RendererCanvasMapbox;
	public ui: UI;

	constructor(id: string) {
		this.divHost = document.getElementById(id) as HTMLDivElement;
		this.divHost.style.position = 'relative';

		this.mapboxWrapper = new MapboxGLWrapper(this.divHost.id);
		this.mapboxWrapper.mouseDown = this.mouseDown
		this.mapboxWrapper.mouseUp = this.mouseUp
		this.mapboxWrapper.mouseClick = this.mouseClick
		this.mapboxWrapper.mouseMove = this.mouseMove

		this.mapboxWrapper.map.on("style.load", () => {

			const threeLayer = new RendererThreeMapbox(this.mapboxWrapper.map);
			this.mapboxWrapper.map.addLayer(threeLayer.createLayer());

			this.mapboxWrapper.map.flyTo({
				center: [144.7937, 13.4443],
				zoom: 15,
				pitch: 60,
				bearing: 20,
				duration: 4000,
			});
		});

		this.rendererCanvas = new RendererCanvasMapbox(this.divHost, this);

		this.ui = new UI(this);
		this.ui.init();


	}
	public mouseDown = (e) => {
		// TODO
	}
	public mouseUp = (e) => {
		// TODO
	}
	public mouseDrag = (e) => {
		// TODO
	}
	public mouseClick = (e) => {
		// TODO
		// console.log('dddd');
		// console.log(e);
		// console.log(e['lngLat']);
		this.rendererCanvas.pts.push([e['lngLat']['lng'], e['lngLat']['lat']])
	}
	public mouseMove = (e) => {
		// TODO
	}
	public keyDown(k: KeyboardEvent) {
		// TODO
	}
	public destroy() {
		this.rendererCanvas.destroy();
		while (this.divHost.lastElementChild) {
			this.divHost.removeChild(this.divHost.lastElementChild);
		}
	}
}
